package wallet

import "sync"

// Wallet holds a balance in cents that several goroutines may read and write.
type Wallet struct {
	mu      sync.Mutex
	balance int
}

// Balance answers the current balance.
func (w *Wallet) Balance() int {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.balance
}

// SetBalance replaces the balance.
func (w *Wallet) SetBalance(cents int) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.balance = cents
}

// Deposit adds cents to the balance.
func (w *Wallet) Deposit(cents int) {
	w.SetBalance(w.Balance() + cents)
}
